#!/usr/bin/env bash
# Point vstd and its builtin crates at the Verus source tree that built the `verus` on PATH,
# so the verifier and vstd always come from the same commit. Writes a gitignored
# .cargo/config.toml; run it again after rebuilding Verus.
set -euo pipefail
: "${VERUS_SOURCE:?source ~/workspaces/verus-stack/env.zsh first}"
here="$(cd "$(dirname "$0")/.." && pwd)"
mkdir -p "$here/.cargo"
cat > "$here/.cargo/config.toml" <<CFG
# generated by scripts/use-local-verus.sh — do not commit
[patch.crates-io]
vstd = { path = "$VERUS_SOURCE/vstd" }
verus_builtin = { path = "$VERUS_SOURCE/builtin" }
verus_builtin_macros = { path = "$VERUS_SOURCE/builtin_macros" }
verus_state_machines_macros = { path = "$VERUS_SOURCE/state_machines_macros" }
CFG
echo "wrote $here/.cargo/config.toml -> $VERUS_SOURCE"
